def setUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory(prefix="ckb-cpp-parser-")
        self.root = Path(self.temp.name)

def parse_fixture(self, name: str) -> dict:
        path = self.FIXTURES / name
        source = path.read_bytes()
        return parse_file(
            {"commit": "cpp-parser-fixture"},
            {"id": f"file-{name}", "path": name, "blob": hashlib.sha1(source).hexdigest(), "language": "cpp"},
            source,
        )

def test_design_session_and_summary_examples_are_schema_valid_only(self) -> None:
        validate_instance(
            "benchmark-session-result.schema.json",
            json.loads((BENCHMARK / "benchmark-session-result.json").read_text(encoding="utf-8")),
        )
        validate_instance(
            "benchmark-summary.schema.json",
            json.loads((BENCHMARK / "benchmark-summary.json").read_text(encoding="utf-8")),
        )

def run_cli(*arguments: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SKILL / "scripts" / "ckb_canvas.py"), *arguments],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="strict",
        check=False,
    )
